// Offer community features such as donate, get involved, share ideas
// etc across the application.
pref("mail.community_features.enabled", true);

// Offer experimental features in settings.
pref("mail.experimental_features_settings.enabled", true);

#ifdef NIGHTLY_BUILD
// Enable the new experimental conversation view based on Gloda.
pref("mail.thread.conversation.enabled", false);
#endif

// Enable the conversion to dark mode for all messages when using a dark theme.
pref("mail.dark-reader.enabled", true);
pref("mail.dark-reader.show-toggle", true);

// Enable address book setup via account hub
pref("mail.accounthub.addressbook.enabled", true);

// Enable Thundermail ui in account hub.
pref("mail.accounthub.thundermail.enabled", true);

// Enable new manual config ui in account hub.
pref("mail.accounthub.manualconfig.enabled", true);

// Export to mobile enabled.
pref("mail.qrexport.enabled", true);

// Export to mobile logging level.
pref("mail.qrexport.loglevel", "Warn");

// New calendar dialog
pref("calendar.dialogs.new.enabled", false);

// Layout and UI settings.
// List view style for the thread pane:
// 0 - Cards view.
// 1 - Table view.
pref("mail.threadpane.listview", 0);

// Row count for the cards view, currently bound to a range between 2 and 3.
pref("mail.threadpane.cardsview.rowcount", 3);

// Whether the OS Authentication is enabled or not.
pref("signon.management.page.os-auth.locked.enabled", false);

#ifdef XP_MACOSX
pref("widget.macos.native-anchored-menus", false);
#endif

// The color used to style primary buttons and elements.
pref("mail.appearance.accentColor", "accent-color");
